// 1. Extract data from the Anthropic node
const inputData = $input.first().json;
let rawText = "";

if (inputData.content && Array.isArray(inputData.content)) {
    const textBlock = inputData.content.find(block => block.type === 'text');
    if (textBlock && textBlock.text) {
        rawText = textBlock.text;
    } else {
        throw new Error("No text block found in the model's content array.");
    }
} else if (inputData.text) {
    rawText = inputData.text;
} else {
    throw new Error("Unexpected output format.");
}

// 2. Clean and parse the JSON (handles both raw and stringified formats)
let data;
try {
    // If the text starts with a quote, it's stringified JSON; parse it first to unescape
    if (rawText.trim().startsWith('"') || rawText.trim().startsWith("'")) {
        rawText = JSON.parse(rawText);
    }

    // Extract the inner JSON if there is extra wrapper text
    const jsonStartIndex = rawText.indexOf('{');
    const jsonEndIndex = rawText.lastIndexOf('}');
    const jsonString = rawText.substring(jsonStartIndex, jsonEndIndex + 1);

    data = JSON.parse(jsonString);
} catch (e) {
    throw new Error("Failed to parse JSON: " + e.message);
}

// 3. Validate and format the parsed data
const required = ['youtube_title', 'pinterest_caption', 'hook', 'scene_1', 'scene_2', 'scene_3', 'on_screen_1', 'on_screen_2', 'on_screen_3'];
const missing = required.filter(k => !data[k] || String(data[k]).trim() === '');
if (missing.length) {
    throw new Error('Claude output missing keys: ' + missing.join(', '));
}

const REF = 'https://acorns.com/share/?shareable_code=REFERRAL_CODE&first_name=Alexander&friend_reward=5';
const out = {};

for (const k of required) {
    out[k] = String(data[k]).trim();
}

out.youtube_title = out.youtube_title.replace(/[<>]/g, '').slice(0, 95);
out.pinterest_caption = out.pinterest_caption.slice(0, 480);
if (!out.pinterest_caption.includes(REF)) {
    out.pinterest_caption = out.pinterest_caption.slice(0, 480 - REF.length - 1) + ' ' + REF;
}
out.referral_link = REF;
out.source_title = $('RSS Feed Monitor').first().json.title || '';
out.source_url = $('RSS Feed Monitor').first().json.link || '';

return [{json: out}];
